INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(201895, 11664, 543, '<td valign="top">Maybe at another time of day, when the interior/exterior exposure could be better balanced?  It''s a shame to have all those lines leading to almost nothing.  The walls do give a great dimensionality to the image, and I love the light on them.</td>', 'Maybe at another time of day, when the interior/exterior exposure could be better balanced?  It''s a shame to have all those lines leading to almost nothing.  The walls do give a great dimensionality to the image, and I love the light on them.', '2003-01-27 22:59:49.000000', NULL, 1),
(201897, 11583, 543, '<td valign="top">I was torn between these and triscuits, then scrapped both ideas for something else.  My only nit here is the lighting.  I like the sidelighitng to bring out the texture in the mini-wheats, but don''t like the hard shadow at R.  Maybe a reflector to fill it a little would be better.  Nice work.</td>', 'I was torn between these and triscuits, then scrapped both ideas for something else.  My only nit here is the lighting.  I like the sidelighitng to bring out the texture in the mini-wheats, but don''t like the hard shadow at R.  Maybe a reflector to fill it a little would be better.  Nice work.', '2003-01-27 23:03:12.000000', NULL, 1),
(201898, 11422, 543, '<td valign="top">This would be better, IMO, with a nice contrasty B/W conversion.</td>', 'This would be better, IMO, with a nice contrasty B/W conversion.', '2003-01-27 23:05:03.000000', NULL, 1),
(201899, 11542, 1280, '<td valign="top">Very nice!</td>', 'Very nice!', '2003-01-27 23:07:44.000000', NULL, 1),
(201900, 11460, 543, '<td valign="top">&lt;vbg&gt;  You need help!  This is a riot!  Great colors and layout.  Only nits are some slightly blown highliights and a pinkish tinge to the eggs.</td>', '<vbg>  You need help!  This is a riot!  Great colors and layout.  Only nits are some slightly blown highliights and a pinkish tinge to the eggs.', '2003-01-27 23:08:58.000000', NULL, 1),
(201901, 11473, 1280, '<td valign="top">Very good!</td>', 'Very good!', '2003-01-27 23:09:54.000000', NULL, 1),
(201902, 11575, 543, '<td valign="top">Now I''m all torn.  I wish I had this in my portfolio, and not a square in sight.  Oh, well... plenty of other people to punish you for that.  Very fine work.</td>', 'Now I''m all torn.  I wish I had this in my portfolio, and not a square in sight.  Oh, well... plenty of other people to punish you for that.  Very fine work.', '2003-01-27 23:11:07.000000', NULL, 1),
