INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(202708, 11611, 3280, '<td valign="top">I think this is a hoot.  I hope everyone understands it!  I wisht that the white corners that show fromt the other "squares" were cropped out.  Good job.</td>', 'I think this is a hoot.  I hope everyone understands it!  I wisht that the white corners that show fromt the other "squares" were cropped out.  Good job.', '2003-01-28 23:34:39.000000', NULL, 1),
(202709, 11517, 3280, '<td valign="top">Nice job, I like the colors and the pie looks great!  It seems like the blue dish is a bit grainy, did you use Neat Image?</td>', 'Nice job, I like the colors and the pie looks great!  It seems like the blue dish is a bit grainy, did you use Neat Image?', '2003-01-28 23:36:06.000000', NULL, 1),
(202710, 11359, 3280, '<td valign="top">Nice shot, good color and lighting.</td>', 'Nice shot, good color and lighting.', '2003-01-28 23:36:35.000000', NULL, 1),
(202711, 11403, 3280, '<td valign="top">This is pretty neat. I know you wanted to show the square but I feel like I would like to see more of the floor perhaps at an angle.</td>', 'This is pretty neat. I know you wanted to show the square but I feel like I would like to see more of the floor perhaps at an angle.', '2003-01-28 23:37:36.000000', NULL, 1),
(202715, 11503, 6008, '<td valign="top">Simple yet effective. I like how the foreground and background compliment each other. I think the sky with the clouds adds an interpretational depth to the image, giving it an imprisoned yet hopefull feel. And it meets the challenge of squares :)</td>', 'Simple yet effective. I like how the foreground and background compliment each other. I think the sky with the clouds adds an interpretational depth to the image, giving it an imprisoned yet hopefull feel. And it meets the challenge of squares :)', '2003-01-29 00:16:36.000000', NULL, 1),
(202716, 11372, 6008, '<td valign="top">It''s an interesting shot, but I feel like the bars are distracting when I focus on the background, and the background too distracting when I focus on the bars. In my opinion a more simpler (plain) background would have helped.</td>', 'It''s an interesting shot, but I feel like the bars are distracting when I focus on the background, and the background too distracting when I focus on the bars. In my opinion a more simpler (plain) background would have helped.', '2003-01-29 00:19:52.000000', NULL, 1),
(202717, 11585, 6008, '<td valign="top">I find the lighting on the bottom three dice a little dark, and a suggestion of movement would have been nice and complimented the caption.</td>', 'I find the lighting on the bottom three dice a little dark, and a suggestion of movement would have been nice and complimented the caption.', '2003-01-29 00:25:12.000000', NULL, 1),
(202719, 11547, 6008, '<td valign="top">I like the movement and the vibrant color of what I assume is a shuttlecock. The lighting is good, and the crop shows enough of the racket to visualise the concept without distracting too much from the (square) strings.</td>', 'I like the movement and the vibrant color of what I assume is a shuttlecock. The lighting is good, and the crop shows enough of the racket to visualise the concept without distracting too much from the (square) strings.', '2003-01-29 00:30:33.000000', NULL, 1),
(202720, 11361, 6008, '<td valign="top">The corner of the box in the top right hand corner is a little distracting, and the shadow of the uppermost red treat is a little dark, but the concept is interesting.</td>', 'The corner of the box in the top right hand corner is a little distracting, and the shadow of the uppermost red treat is a little dark, but the concept is interesting.', '2003-01-29 00:33:52.000000', NULL, 1),
(202721, 11415, 6008, '<td valign="top">I would probably have cropped the top more and not been as tight on the bottom of the second square. I like how the texture of the paper shows vibrant, and the concept is interesting.</td>', 'I would probably have cropped the top more and not been as tight on the bottom of the second square. I like how the texture of the paper shows vibrant, and the concept is interesting.', '2003-01-29 00:37:20.000000', NULL, 1),
(202723, 11481, 6008, '<td valign="top">I feel the black piece is a little too dark and the crop too tight on the taller piece. What I assume is a soft focus adds to the feel of the b&amp;w imagery.<br/></td>', 'I feel the black piece is a little too dark and the crop too tight on the taller piece. What I assume is a soft focus adds to the feel of the b&w imagery.', '2003-01-29 00:44:39.000000', NULL, 1),
