(204900, 11389, 3280, '<td valign="top">Cool shot, nice focus and great colors and textures. I really like it a bunch!</td>', 'Cool shot, nice focus and great colors and textures. I really like it a bunch!', '2003-02-02 06:25:07.000000', NULL, 1),
(204901, 11408, 3280, '<td valign="top">Humerous. I wish your background was  a bit whiter so that the box would stand out more.</td>', 'Humerous. I wish your background was  a bit whiter so that the box would stand out more.', '2003-02-02 06:27:01.000000', NULL, 1),
